import test from 'node:test';
import assert from 'node:assert/strict';
import { CYCLES, monthlyCents, nextCharge } from '../src/cycles.js';

test('every stored cycle name is known', () => {
  assert.ok(CYCLES.includes('monthly'));
  assert.ok(CYCLES.includes('yearly'));
});

test('a monthly plan costs its price a month', () => {
  assert.equal(monthlyCents({ price: 1299, cycle: 'monthly' }), 1299);
  assert.equal(monthlyCents({ price: 0, cycle: 'monthly' }), 0);
});

test('a yearly plan costs a twelfth of its price a month, cut to the cent', () => {
  assert.equal(monthlyCents({ price: 12000, cycle: 'yearly' }), 1000);
  assert.equal(monthlyCents({ price: 11999, cycle: 'yearly' }), 999);
  assert.equal(monthlyCents({ price: 1450, cycle: 'yearly' }), 120);
});

test('the next charge of a plan that charges today is today', () => {
  assert.equal(nextCharge({ cycle: 'monthly', since: '2026-08-24' }, '2026-10-24'), '2026-10-24');
  assert.equal(nextCharge({ cycle: 'yearly', since: '2025-10-24' }, '2026-10-24'), '2026-10-24');
});

test('a plan that has not started yet next charges on its first day', () => {
  assert.equal(nextCharge({ cycle: 'monthly', since: '2026-11-05' }, '2026-10-24'), '2026-11-05');
});

test('monthly charges started on the 31st fall on the last day of shorter months', () => {
  assert.equal(nextCharge({ cycle: 'monthly', since: '2026-01-31' }, '2026-02-01'), '2026-02-28');
  assert.equal(nextCharge({ cycle: 'monthly', since: '2026-01-31' }, '2026-03-01'), '2026-03-31');
  assert.equal(nextCharge({ cycle: 'monthly', since: '2026-01-31' }, '2026-04-02'), '2026-04-30');
});

test('a yearly plan charges once a year on the same day', () => {
  assert.equal(nextCharge({ cycle: 'yearly', since: '2023-03-02' }, '2026-10-24'), '2027-03-02');
  assert.equal(nextCharge({ cycle: 'yearly', since: '2024-02-29' }, '2026-10-24'), '2027-02-28');
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { formatEuros, parseEuros, plainEuros } from '../src/money.js';

test('parseEuros reads what people type', () => {
  assert.equal(parseEuros('12'), 1200);
  assert.equal(parseEuros('12.5'), 1250);
  assert.equal(parseEuros('12.99'), 1299);
  assert.equal(parseEuros('1,299.00'), 129900);
  assert.equal(parseEuros(' 7 '), 700);
});

test('parseEuros rejects what is not an amount', () => {
  for (const text of ['', 'abc', '12.345', '-5', '1,29', '12,99']) assert.equal(parseEuros(text), null, text);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(0), '€0.00');
  assert.equal(formatEuros(-250), '-€2.50');
});

test('plainEuros writes a plain decimal', () => {
  assert.equal(plainEuros(129900), '1299.00');
  assert.equal(plainEuros(5), '0.05');
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { upcoming } from '../src/renewals.js';

const plan = (name, cycle, since, price = 1000) => ({ name, price, cycle, since });

test('lists the charges inside the window, a charge today included', () => {
  const subs = [plan('Today', 'monthly', '2026-09-24'), plan('In a week', 'monthly', '2026-08-31'), plan('Later', 'yearly', '2025-12-01')];
  const rows = upcoming(subs, '2026-10-24', 7);
  assert.deepEqual(rows.map((r) => [r.name, r.date, r.inDays]), [['Today', '2026-10-24', 0], ['In a week', '2026-10-31', 7]]);
});

test('each row carries a short label for people', () => {
  const [row] = upcoming([plan('Netflix', 'monthly', '2026-09-27', 1299)], '2026-10-24', 7);
  assert.deepEqual(row, { name: 'Netflix', date: '2026-10-27', when: '27 Oct', inDays: 3, price: 1299, cycle: 'monthly' });
});

test('lists upcoming charges soonest first, across a month boundary', () => {
  const subs = [plan('Gym', 'monthly', '2026-09-02'), plan('Music', 'monthly', '2026-09-30')];
  const rows = upcoming(subs, '2026-10-25', 14);
  assert.deepEqual(rows.map((r) => r.date), ['2026-10-30', '2026-11-02']);
});

test('nothing in the window gives an empty list', () => {
  assert.deepEqual(upcoming([plan('Domain', 'yearly', '2026-03-02')], '2026-10-24'), []);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const BIN = fileURLToPath(new URL('../bin/subtrack.js', import.meta.url));

function cli(file, ...args) {
  const r = spawnSync(process.execPath, [BIN, ...args, '--file', file], { encoding: 'utf8' });
  return { code: r.status, out: r.stdout, err: r.stderr };
}

function withFile(fn) {
  const dir = mkdtempSync(join(tmpdir(), 'subtrack-cli-'));
  try {
    fn(join(dir, 'subs.json'));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

test('add, list and total', () => withFile((file) => {
  assert.equal(cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-14').code, 0);
  assert.equal(cli(file, 'add', 'Domain name', '24', '--every', 'year', '--since', '2026-03-02').code, 0);
  const list = cli(file, 'list');
  assert.equal(list.code, 0);
  assert.match(list.out, /Netflix\s+€12\.99 monthly\s+€12\.99 a month/);
  assert.match(list.out, /Domain name\s+€24\.00 yearly\s+€2\.00 a month/);
  assert.equal(cli(file, 'total').out, 'Monthly total: €14.99 (2 plans)\n');
}));

test('renewals shows what charges next', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-27');
  const r = cli(file, 'renewals', '--within', '7', '--today', '2026-10-24');
  assert.equal(r.code, 0);
  assert.equal(r.out, '27 Oct  Netflix  €12.99\n');
  assert.equal(cli(file, 'renewals', '--within', '2', '--today', '2026-10-24').out, 'Nothing renews in the next 2 days.\n');
}));

test('export writes CSV', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-27');
  assert.equal(cli(file, 'export', '--today', '2026-10-24').out,
    'name,price,cycle,monthly_cost,next_charge\nNetflix,12.99,monthly,12.99,2026-10-27\n');
}));

test('bad input exits 2 with a message', () => withFile((file) => {
  for (const args of [['add', 'X', 'abc'], ['add', 'X'], ['frobnicate'], ['renewals', '--within', 'soon'], ['add', 'X', '5', '--every', 'fortnight']]) {
    const r = cli(file, ...args);
    assert.equal(r.code, 2, args.join(' '));
    assert.match(r.err, /^subtrack: /, args.join(' '));
  }
}));

test('adding the same name twice fails', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99');
  const r = cli(file, 'add', 'netflix', '9.99');
  assert.equal(r.code, 1);
  assert.match(r.err, /already on the list/);
}));
{
  "name": "subtrack",
  "version": "0.3.0",
  "private": true,
  "description": "Keep track of your subscriptions: what they cost you each month and what renews next.",
  "type": "module",
  "bin": {
    "subtrack": "bin/subtrack.js"
  },
  "scripts": {
    "test": "node --test"
  },
  "engines": {
    "node": ">=20"
  }
}

